conditions.expression:
moreTool === 'savedRecipes' && (
          <SavedRecipesModal
            editingRecipe={editingRecipe}
            localOnly={!user}
            onClose={() => setMoreTool(null)}
            onLoad={(saved) => {
              applyRecipe(saved.recipe);
              setEditingRecipe({ id: saved.recipe_id, name: saved.name });
              setMoreTool(null);
            }}
            onSave={saveNamedRecipe}
          />
        )
